INSERT INTO feature VALUES('pr-refactoring','workflow','Every pull request answers whether a refactoring is justified',NULL,'implemented','ordinary',NULL,'A pull request body answers `## Refactoring` with `yes`, `maybe` or `no`, a `yes` or `maybe` with a table of kind, where and observation; `pr:open` refuses a body without it, and `check:refactoring` refuses a `Where` that names no item of the workspace''s rustdoc and no tracked path.',NULL,'.config/bodies/opening.json .config/bodies/refactoring.json',NULL,NULL);
